#!/bin/bash\n\n# SMG4 Setup Assistant - Easter Egg\n# \"About this amazing setup experience\"\n\nsource \"$(dirname \"$0\")/scripts/colors.sh\"\n\nclear\n\ncat << 'EOF'\n\n    ╔════════════════════════════════════════════════════════════════╗\n    ║                                                                ║\n    ║              🎮 ABOUT THIS SETUP ASSISTANT 🎮                 ║\n    ║                                                                ║\n    ║    Powered by SMG4 - The Legend Himself!                      ║\n    ║                                                                ║\n    ╚════════════════════════════════════════════════════════════════╝\n\nEOF\n\necho \"\"\nsmg4_say \"Hey! It's me, SMG4! Let me tell you about myself...\"\necho \"\"\nsleep 2\n\ncat << 'EOF'\n\n┌─────────────────────────────────────────────────────────────────────┐\n│ WHO IS SMG4?                                                        │\n├─────────────────────────────────────────────────────────────────────┤\n│                                                                     │\n│ I'm Stefano Monteleone, known as SMG4 on YouTube. I make glitchy  │\n│ video game content, specifically Mario series videos that range    │\n│ from hilarious to chaotic to downright absurd.                     │\n│                                                                     │\n│ My channel has millions of subscribers, and my videos have become  │\n│ internet culture icons. I'm known for:                             │\n│                                                                     │\n│  • Ridiculous Mario glitch compilations                            │\n│  • Over-the-top humor and memes                                    │\n│  • Glitchy but surprisingly heartfelt storytelling                 │\n│  • Legendary characters like Luigi, Bob, and Fishy Boopkins       │\n│  • Absolute chaos disguised as entertainment                       │\n│                                                                     │\n└─────────────────────────────────────────────────────────────────────┘\n\nEOF\n\nsleep 2\n\necho \"\"\nsmg4_say \"So why am I helping you set up a Linux distro?\"\necho \"\"\n\ncat << 'EOF'\n\n┌─────────────────────────────────────────────────────────────────────┐\n│ WHY smg4OS EXISTS                                                   │\n├─────────────────────────────────────────────────────────────────────┤\n│                                                                     │\n│ smg4OS is a fan-made Linux distribution inspired by the SMG4       │\n│ universe. It combines:                                             │\n│                                                                     │\n│  • Linux's power and flexibility                                   │\n│  • Open-source philosophy and community                            │\n│  • SMG4's signature chaotic fun energy                             │\n│  • Professional quality with meme aesthetics                       │\n│  • Gaming optimization and modern tools                            │\n│                                                                     │\n│ This setup assistant brings SMG4's personality to system setup     │\n│ - making installation fun while keeping things functional.         │\n│                                                                     │\n└─────────────────────────────────────────────────────────────────────┘\n\nEOF\n\necho \"\"\nsmg4_say \"And yes, I'm *actually* here to help. Shocking, I know.\"\necho \"\"\n\ncat << 'EOF'\n\n┌─────────────────────────────────────────────────────────────────────┐\n│ WHAT THIS ASSISTANT DOES                                            │\n├─────────────────────────────────────────────────────────────────────┤\n│                                                                     │\n│ This setup wizard guides you through:                              │\n│                                                                     │\n│  ✓ System configuration (hostname, users, packages)                │\n│  ✓ Desktop environment setup                                       │\n│  ✓ Theme and wallpaper selection                                   │\n│  ✓ Boot menu customization                                         │\n│  ✓ Development tool installation                                   │\n│  ✓ Quick setup for impatient people                                │\n│  ✓ System information display                                      │\n│                                                                     │\n│ All with humor, personality, and actual functionality!             │\n│                                                                     │\n└─────────────────────────────────────────────────────────────────────┘\n\nEOF\n\necho \"\"\nsmg4_say \"So basically, I'm here to make Linux setup fun. You're welcome!\"\necho \"\"\n\ncat << 'EOF'\n\n┌─────────────────────────────────────────────────────────────────────┐\n│ SMG4 FACTS                                                          │\n├─────────────────────────────────────────────────────────────────────┤\n│                                                                     │\n│  Channel:            SMG4 (YouTube)                                │\n│  Real Name:          Stefano Monteleone                            │\n│  Based In:           Italy                                         │\n│  Content:            Mario glitch videos & animations              │\n│  Subscribers:        Multiple millions!                            │\n│  Famous For:         Bob Bobowski, Luigi, Fishy Boopkins           │\n│  Running Gag:        \"Memes\", glitches, chaos                      │\n│  Achievement:        Making glitches into art                      │\n│                                                                     │\n└─────────────────────────────────────────────────────────────────────┘\n\nEOF\n\necho \"\"\nsmg4_say \"Alright, enough about me. Let's get your system set up!\"\necho \"\"\nsleep 1\n\necho -e \"${GREEN}═════════════════════════════════════════════════════════════════${NC}\"\necho \"\"\necho -e \"${CYAN}You can now close this and run:${NC}\"\necho -e \"${GOLD}  ./setup-wizard/smg4-setup.sh${NC}\"\necho \"\"\necho -e \"${CYAN}To start your smg4OS setup journey!${NC}\"\necho \"\"\necho -e \"${MAGENTA}Made with ❤️  and powered by memes!${NC}\"\necho \"\"\necho -e \"${GREEN}═════════════════════════════════════════════════════════════════${NC}\"\n"